import { Check, LoaderCircle, AlertCircle } from "lucide-react";
import type { ButtonHTMLAttributes } from "react";
export type ButtonState = "idle" | "loading" | "success" | "error";
export type ButtonVariant = "primary" | "secondary" | "ghost" | "destructive";
type Base = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "aria-label"> & {
  variant?: ButtonVariant;
  state?: ButtonState;
  size?: "sm" | "md";
};
export type ButtonProps = Base &
  (
    | { iconOnly: true; "aria-label": string }
    | { iconOnly?: false; "aria-label"?: string }
  );
export function Button({
  variant = "primary",
  state = "idle",
  size = "sm",
  disabled,
  className = "",
  children,
  iconOnly = false,
  type = "button",
  ...props
}: ButtonProps) {
  const StateIcon =
    state === "loading"
      ? LoaderCircle
      : state === "success"
        ? Check
        : AlertCircle;
  return (
    <button
      {...props}
      type={type}
      disabled={disabled || state === "loading"}
      aria-busy={state === "loading" || undefined}
      data-state={state}
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      className={`tz-button ${className}`}
    >
      {state !== "idle" && (
        <StateIcon
          aria-hidden="true"
          className={state === "loading" ? "tz-spinner" : ""}
          size={16}
        />
      )}
      {(!iconOnly || state === "idle") && (
        <span className="tz-button-label" key={state}>
          {children}
        </span>
      )}
    </button>
  );
}

import * as Primitive from "@radix-ui/react-dropdown-menu";
import { useState } from "react";
import type { ReactElement, ReactNode } from "react";
import { useSystem } from "./useSystem";
export interface MenuItem {
  id: string;
  label: string;
  icon?: ReactNode;
  shortcut?: string;
  disabled?: boolean;
  destructive?: boolean;
  separatorBefore?: boolean;
  onSelect?: () => void;
}
export interface DropdownMenuProps {
  trigger: ReactElement;
  items: MenuItem[];
  align?: "start" | "end";
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}
export function DropdownMenu({
  trigger,
  items,
  align = "start",
  open,
  onOpenChange,
}: DropdownMenuProps) {
  const { container, config } = useSystem();
  const [localOpen, setLocalOpen] = useState(false);
  function changeOpen(value: boolean) {
    setLocalOpen(value);
    onOpenChange?.(value);
  }
  return (
    <Primitive.Root
      modal={false}
      dir={config.direction}
      open={open ?? localOpen}
      onOpenChange={changeOpen}
    >
      <Primitive.Trigger asChild>{trigger}</Primitive.Trigger>
      <Primitive.Portal container={container}>
        <Primitive.Content
          className="tz-menu"
          sideOffset={7}
          align={align}
          collisionPadding={12}
          onKeyDown={(event) => {
            if (event.key === "Tab") {
              event.preventDefault();
              changeOpen(false);
            }
          }}
        >
          {items.map((item) => (
            <div key={item.id}>
              {item.separatorBefore && (
                <Primitive.Separator className="tz-menu-separator" />
              )}
              <Primitive.Item
                className="tz-menu-item"
                disabled={item.disabled}
                data-destructive={item.destructive || undefined}
                onSelect={item.onSelect}
                onPointerLeave={(event) => {
                  // Animation/scrolling can move an unfocused item away from a
                  // stationary pointer. Its leave must not clear keyboard focus.
                  if (
                    event.currentTarget !==
                    event.currentTarget.ownerDocument.activeElement
                  ) {
                    event.preventDefault();
                  }
                }}
              >
                {item.icon && <span aria-hidden="true">{item.icon}</span>}
                <span>{item.label}</span>
                {item.shortcut && <kbd dir="ltr">{item.shortcut}</kbd>}
              </Primitive.Item>
            </div>
          ))}
        </Primitive.Content>
      </Primitive.Portal>
    </Primitive.Root>
  );
}

import { useState } from "react";
import type { CSSProperties, ReactNode } from "react";
import { DirectionProvider } from "@radix-ui/react-direction";
import { accentColors, defaultConfig } from "./config";
import type { SystemConfig } from "./config";
import { SystemContext } from "./useSystem";
export function SystemProvider({
  config = defaultConfig,
  children,
}: {
  config?: SystemConfig;
  children: ReactNode;
}) {
  const [container, setContainer] = useState<HTMLDivElement | null>(null);
  return (
    <DirectionProvider dir={config.direction}>
      <SystemContext.Provider value={{ config, container }}>
        <div
          ref={setContainer}
          className="tiraz-system"
          dir={config.direction}
          data-theme={config.theme}
          data-density={config.density}
          data-typography={config.typography ?? "standard"}
          data-reduced-motion={config.reducedMotion}
          style={
            {
              "--action": accentColors[config.accent][config.theme],
              "--radius": `${config.radius}px`,
              colorScheme: config.theme,
            } as CSSProperties
          }
        >
          {children}
        </div>
      </SystemContext.Provider>
    </DirectionProvider>
  );
}

import * as Primitive from "@radix-ui/react-dialog";
import { X } from "lucide-react";
import { useState } from "react";
import type { ReactElement, ReactNode } from "react";
import { SystemContext, useSystem } from "./useSystem";
export interface SheetProps {
  trigger: ReactElement;
  title: string;
  description: string;
  closeLabel: string;
  children: ReactNode;
  footer?: ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  side?: "right" | "left";
}
export function Sheet({
  trigger,
  title,
  description,
  closeLabel,
  children,
  footer,
  open,
  onOpenChange,
  side,
}: SheetProps) {
  const { container, config } = useSystem();
  const [content, setContent] = useState<HTMLDivElement | null>(null);
  const resolvedSide = side ?? (config.direction === "rtl" ? "right" : "left");
  return (
    <Primitive.Root open={open} onOpenChange={onOpenChange}>
      <Primitive.Trigger asChild>{trigger}</Primitive.Trigger>
      <Primitive.Portal container={container}>
        <Primitive.Overlay className="tz-sheet-backdrop" />
        <Primitive.Content
          ref={setContent}
          className="tz-sheet"
          data-side={resolvedSide}
          dir={config.direction}
        >
          <SystemContext.Provider value={{ config, container: content }}>
            <header className="tz-sheet-header">
              <div>
                <Primitive.Title>{title}</Primitive.Title>
                <Primitive.Description>{description}</Primitive.Description>
              </div>
              <Primitive.Close
                className="tz-icon-button"
                aria-label={closeLabel}
              >
                <X size={18} />
              </Primitive.Close>
            </header>
            <div className="tz-sheet-body">{children}</div>
            {footer && <footer className="tz-sheet-footer">{footer}</footer>}
          </SystemContext.Provider>
        </Primitive.Content>
      </Primitive.Portal>
    </Primitive.Root>
  );
}

/** Dismiss a Sheet from caller-owned footer content. */
export const SheetClose = Primitive.Close;

import * as Primitive from "@radix-ui/react-switch";
import { useId } from "react";
import type { ComponentProps } from "react";
export interface SwitchProps extends Omit<
  ComponentProps<typeof Primitive.Root>,
  "children" | "asChild"
> {
  label: string;
  description?: string;
}
export function Switch({
  label,
  description,
  id,
  className = "",
  "aria-describedby": describedBy,
  ...props
}: SwitchProps) {
  const uid = useId();
  const controlId = id ?? uid;
  return (
    <div
      className={`tz-switch-field ${className}`}
      data-disabled={props.disabled || undefined}
    >
      <div className="tz-switch-copy">
        <label htmlFor={controlId}>{label}</label>
        {description && <p id={`${controlId}-description`}>{description}</p>}
      </div>
      <Primitive.Root
        {...props}
        id={controlId}
        aria-describedby={
          [describedBy, description ? `${controlId}-description` : undefined]
            .filter(Boolean)
            .join(" ") || undefined
        }
        className="tz-switch"
      >
        <Primitive.Thumb className="tz-switch-thumb" />
      </Primitive.Root>
    </div>
  );
}

import * as Primitive from "@radix-ui/react-tabs";
import { useLayoutEffect, useRef, useState } from "react";
import type { CSSProperties, ReactNode } from "react";
import { useSystem } from "./useSystem";
export interface TabItem {
  value: string;
  label: ReactNode;
  content: ReactNode;
  disabled?: boolean;
}
export interface TabsProps {
  items: TabItem[];
  label: string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  variant?: "underline" | "segment";
  className?: string;
}
export function Tabs({
  items,
  label,
  value,
  defaultValue = items.find((item) => !item.disabled)?.value,
  onValueChange,
  variant = "underline",
  className = "",
}: TabsProps) {
  const { config } = useSystem();
  const [local, setLocal] = useState(defaultValue);
  const active = value ?? local;
  const list = useRef<HTMLDivElement>(null);
  const [indicator, setIndicator] = useState({ width: 0, x: 0 });
  useLayoutEffect(() => {
    const el = list.current;
    if (!el) return;
    const measure = () => {
      const tab = el.querySelector<HTMLElement>('[data-state="active"]');
      if (tab) {
        const rect = tab.getBoundingClientRect();
        const parent = el.getBoundingClientRect();
        setIndicator({
          width: rect.width,
          x: rect.left - parent.left + el.scrollLeft,
        });
      }
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    void document.fonts?.ready.then(measure);
    return () => observer.disconnect();
  }, [active, config.density, config.direction, items]);
  return (
    <Primitive.Root
      className={`tz-tabs ${className}`}
      value={active}
      onValueChange={(v) => {
        setLocal(v);
        onValueChange?.(v);
      }}
      dir={config.direction}
      data-variant={variant}
    >
      <Primitive.List ref={list} className="tz-tab-list" aria-label={label}>
        <span
          aria-hidden="true"
          className="tz-tab-indicator"
          style={
            {
              width: indicator.width,
              transform: `translateX(${indicator.x}px)`,
            } as CSSProperties
          }
        />
        {items.map((item) => (
          <Primitive.Trigger
            key={item.value}
            className="tz-tab"
            value={item.value}
            disabled={item.disabled}
          >
            {item.label}
          </Primitive.Trigger>
        ))}
      </Primitive.List>
      {items.map((item) => (
        <Primitive.Content
          className="tz-tab-panel"
          key={item.value}
          value={item.value}
        >
          {item.content}
        </Primitive.Content>
      ))}
    </Primitive.Root>
  );
}

import * as Primitive from "@radix-ui/react-toast";
import { useId, useRef, useState } from "react";
import { CircleCheck, CircleAlert, Info, X } from "lucide-react";
import type { ReactNode } from "react";
import { ToastContext } from "./useToast";
import type { ToastMessage } from "./useToast";
interface Entry extends ToastMessage {
  id: string;
  open: boolean;
  returnFocus: HTMLElement | null;
}
export function ToastProvider({
  children,
  closeLabel,
  label,
}: {
  children: ReactNode;
  closeLabel: string;
  label: string;
}) {
  const [{ entries, generation }, setSession] = useState({
    entries: [] as Entry[],
    generation: 0,
  });
  const uid = useId();
  const viewport = useRef<HTMLOListElement>(null);
  function toast(message: ToastMessage) {
    const returnFocus =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
    const entry: Entry = {
      ...message,
      id: `${uid}-${crypto.randomUUID()}`,
      open: true,
      returnFocus,
    };
    setSession((prev) => {
      const active = prev.entries.filter((item) => item.open);
      return {
        entries: [...active.slice(-2), entry],
        generation: active.length ? prev.generation : prev.generation + 1,
      };
    });
  }
  return (
    <ToastContext.Provider value={{ toast }}>
      {children}
      {/* Reset Radix's pause state for a new batch without remounting callers. */}
      <Primitive.Provider
        key={generation}
        duration={5000}
        swipeDirection="down"
        label={label}
      >
        {entries.map((entry) => {
          const Icon =
            entry.tone === "error"
              ? CircleAlert
              : entry.tone === "success"
                ? CircleCheck
                : Info;
          return (
            <Primitive.Root
              key={entry.id}
              className="tz-toast"
              data-tone={entry.tone ?? "info"}
              open={entry.open}
              duration={entry.duration}
              onOpenChange={(open) => {
                if (!open) {
                  // Leave the viewport before its last toast removes Radix's
                  // focus/hover resume listeners; future messages must expire.
                  if (
                    viewport.current &&
                    document.activeElement === viewport.current
                  ) {
                    if (entry.returnFocus?.isConnected)
                      entry.returnFocus.focus();
                    if (viewport.current.contains(document.activeElement))
                      (document.activeElement as HTMLElement).blur();
                  }
                  setSession((prev) => ({
                    ...prev,
                    entries: prev.entries.map((item) =>
                      item.id === entry.id ? { ...item, open: false } : item,
                    ),
                  }));
                }
              }}
            >
              <Icon className="tz-toast-icon" aria-hidden="true" size={21} />
              <div>
                <Primitive.Title className="tz-toast-title">
                  {entry.title}
                </Primitive.Title>
                {entry.description && (
                  <Primitive.Description className="tz-toast-description">
                    {entry.description}
                  </Primitive.Description>
                )}
              </div>
              <Primitive.Close
                className="tz-icon-button"
                aria-label={closeLabel}
              >
                <X size={16} />
              </Primitive.Close>
            </Primitive.Root>
          );
        })}
        <Primitive.Viewport
          ref={viewport}
          className="tz-toast-viewport"
          label={label}
        />
      </Primitive.Provider>
    </ToastContext.Provider>
  );
}

.tiraz-system,
.tiraz-system *,
.tiraz-system *::before,
.tiraz-system *::after {
  box-sizing: border-box;
}
.tiraz-system :where(button, input, select, textarea) {
  font: inherit;
}
.tiraz-system :where(button) {
  cursor: pointer;
}
.tiraz-system :where(button:disabled) {
  cursor: not-allowed;
}
.tiraz-system
  :where(button, a, input, select, textarea, [tabindex]):focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
}
.tiraz-system :where(svg) {
  flex-shrink: 0;
}
.tz-button {
  --button-height: var(--control-height);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--control-gap);
  min-block-size: var(--button-height);
  padding-inline: var(--control-padding);
  padding-block: 3px;
  font-size: var(--text-body);
  border: 1px solid transparent;
  border-radius: var(--radius);
  font-weight: var(--weight-medium);
  line-height: 1.6;
  transition:
    background var(--motion-fast),
    border-color var(--motion-fast),
    transform var(--motion-fast),
    box-shadow var(--motion-fast);
  background: var(--action);
  color: var(--action-text);
  box-shadow: var(--shadow-control);
  white-space: nowrap;
}
.tz-button[data-variant="secondary"] {
  background: var(--surface);
  color: var(--text);
  border-color: var(--border-strong);
}
.tz-button[data-variant="ghost"] {
  background: transparent;
  color: var(--text-secondary);
  box-shadow: none;
}
.tz-button[data-variant="destructive"] {
  background: var(--danger-soft);
  border-color: color-mix(in srgb, var(--danger) 25%, var(--surface));
  color: var(--danger);
}
@media (hover: hover) {
  .tz-button[data-state="idle"]:not(:disabled):hover {
    background: var(--action-hover);
  }
  .tz-button[data-state="idle"][data-variant="secondary"]:not(:disabled):hover,
  .tz-button[data-state="idle"][data-variant="ghost"]:not(:disabled):hover {
    background: var(--surface-hover);
  }
  .tz-button[data-state="idle"][data-variant="destructive"]:not(
      :disabled
    ):hover {
    background: color-mix(in srgb, var(--danger) 15%, var(--surface));
  }
}
.tz-button:not(:disabled):active {
  transform: translateY(1px);
  box-shadow: none;
}
.tz-button:disabled {
  opacity: 0.48;
}
.tz-button[data-state="loading"] {
  opacity: 0.75;
  cursor: wait;
}
.tz-button[data-state="success"] {
  background: var(--success-soft);
  color: var(--success);
  border-color: color-mix(in srgb, var(--success) 25%, var(--surface));
}
.tz-button[data-state="error"] {
  background: var(--danger-soft);
  color: var(--danger);
  border-color: color-mix(in srgb, var(--danger) 25%, var(--surface));
}
.tz-button[data-size="sm"] {
  --button-height: var(--control-small);
  padding-block: 2px;
  padding-inline: var(--control-small-padding);
}
.tz-button[data-icon-only] {
  inline-size: var(--button-height);
  padding-inline: 0;
}
.tz-button-label {
  display: inline-flex;
  align-items: center;
  gap: var(--control-gap);
  animation: tz-label-in var(--motion-state) var(--ease);
}
.tz-spinner {
  animation: tz-spin 900ms linear infinite;
}
.tz-icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: 32px;
  block-size: 32px;
  background: transparent;
  color: var(--text-secondary);
  border: 0;
  border-radius: var(--radius-small);
}
.tz-icon-button:hover {
  background: var(--surface-hover);
}
.tz-tab-list {
  display: flex;
  position: relative;
  border-block-end: 1px solid var(--border);
  isolation: isolate;
  overflow-x: auto;
}
.tz-tab {
  color: var(--text-secondary);
  white-space: nowrap;
  position: relative;
  border: 0;
  background: transparent;
  min-block-size: var(--control-height);
  padding-inline: var(--space-5);
  padding-block: var(--tab-padding);
  font-weight: var(--weight-medium);
}
.tz-tab[data-state="active"] {
  color: var(--action);
}
.tz-tab:disabled {
  opacity: 0.45;
}
.tz-tab-indicator {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  background: var(--action);
  transition:
    width var(--motion-state) var(--ease),
    transform var(--motion-state) var(--ease);
  pointer-events: none;
  z-index: -1;
  border-start-start-radius: 2px;
  border-start-end-radius: 2px;
}
.tz-tab-panel {
  outline-offset: -2px !important;
}
.tz-tabs[data-variant="segment"] > .tz-tab-list {
  display: inline-flex;
  background: var(--surface-subtle);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 3px;
}
.tz-tabs[data-variant="segment"] > .tz-tab-list > .tz-tab {
  min-block-size: var(--control-small);
  padding-block: 3px;
}
.tz-tabs[data-variant="segment"] > .tz-tab-list > .tz-tab-indicator {
  bottom: 3px;
  height: calc(100% - 6px);
  background: var(--surface);
  border-radius: var(--radius-small);
  box-shadow: var(--shadow-control);
}
.tz-switch-field {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--row-gap);
  min-block-size: var(--control-height);
}
.tz-switch-copy label {
  font-weight: var(--weight-medium);
  cursor: pointer;
}
.tz-switch-copy p {
  font-size: var(--text-meta);
  color: var(--text-secondary);
  margin: 2px 0 0;
}
.tz-switch-field[data-disabled] .tz-switch {
  opacity: 0.5;
}
.tz-switch-field[data-disabled] label {
  color: var(--text-secondary);
  cursor: not-allowed;
}
.tz-switch {
  position: relative;
  border: 1px solid var(--switch-track);
  border-radius: 100px;
  background: var(--switch-track);
  inline-size: 38px;
  block-size: 22px;
  flex-shrink: 0;
  padding: 2px;
  transition:
    background var(--motion-state),
    border-color var(--motion-state);
  touch-action: manipulation;
}
.tz-switch[data-state="checked"] {
  background: var(--action);
  border-color: var(--action);
}
.tz-switch-thumb {
  display: block;
  inline-size: 16px;
  block-size: 16px;
  border-radius: 50%;
  background: var(--surface);
  box-shadow: 0 1px 3px #00000026;
  transform: translateX(0);
  transition: transform var(--motion-state) var(--ease);
}
.tz-switch[data-state="checked"] .tz-switch-thumb {
  transform: translateX(16px);
  background: var(--action-text);
}
.tz-switch:dir(rtl)[data-state="checked"] .tz-switch-thumb {
  transform: translateX(-16px);
}
.tz-menu {
  z-index: 60;
  inline-size: 224px;
  max-inline-size: calc(100vw - 24px);
  max-block-size: var(
    --radix-dropdown-menu-content-available-height,
    calc(100dvh - 24px)
  );
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--space-1);
  border-radius: var(--radius-panel);
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-popover);
  transform-origin: var(--radix-dropdown-menu-content-transform-origin);
  animation: tz-menu-in var(--motion-enter) var(--ease);
}
.tz-menu[data-state="closed"] {
  animation: tz-menu-out var(--motion-exit) var(--ease);
}
.tz-menu-item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  border-radius: var(--radius-small);
  padding-block: var(--menu-item-padding);
  padding-inline: var(--space-3);
  outline: none;
  cursor: pointer;
  min-block-size: var(--control-height);
}
.tz-menu-item[data-highlighted] {
  background: var(--surface-subtle);
  color: var(--action);
}
.tz-menu-item[data-disabled] {
  opacity: 0.4;
  cursor: not-allowed;
}
.tz-menu-item[data-destructive] {
  color: var(--danger);
}
.tz-menu-item kbd {
  margin-inline-start: auto;
  font: 11px var(--font-mono);
  color: var(--text-muted);
}
.tz-menu-separator {
  block-size: 1px;
  background: var(--border);
  margin: 4px;
}
.tz-sheet-backdrop {
  position: fixed;
  inset: 0;
  background: #0c18114d;
  z-index: 90;
  animation: tz-fade-in var(--motion-enter);
}
.tz-sheet-backdrop[data-state="closed"] {
  animation: tz-fade-out var(--motion-exit);
}
.tz-sheet {
  position: fixed;
  z-index: 91;
  inset-block: 0;
  inline-size: min(440px, calc(100vw - 24px));
  background: var(--surface);
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-overlay);
  animation: tz-sheet-in var(--motion-enter) var(--ease);
}
.tz-sheet[data-side="right"] {
  right: 0;
  --sheet-offset: 100%;
  border-inline-end: 1px solid var(--border);
}
.tz-sheet[data-side="left"] {
  left: 0;
  --sheet-offset: -100%;
  border-inline-start: 1px solid var(--border);
}
.tz-sheet[data-state="closed"] {
  animation: tz-sheet-out var(--motion-exit) var(--ease);
}
.tz-sheet-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-4);
  padding: var(--space-6);
  border-block-end: 1px solid var(--border);
}
.tz-sheet-header h2 {
  font-size: var(--text-heading);
  font-weight: var(--weight-semibold);
  margin: 0;
}
.tz-sheet-header p {
  font-size: var(--text-meta);
  color: var(--text-secondary);
  margin: 6px 0 0;
}
.tz-sheet-body {
  flex: 1;
  overflow-y: auto;
  padding: var(--space-6);
}
.tz-sheet-footer {
  border-block-start: 1px solid var(--border);
  padding: var(--space-5) var(--space-6);
  display: flex;
  gap: var(--space-2);
  justify-content: flex-end;
}
.tz-toast-viewport {
  position: fixed;
  z-index: 100;
  inset-block-end: 20px;
  inset-inline-end: 20px;
  inline-size: min(370px, calc(100vw - 32px));
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  outline: none;
}
.tz-toast {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-panel);
  background: var(--surface);
  padding: var(--space-4);
  box-shadow: var(--shadow-popover);
  animation: tz-toast-in var(--motion-enter) var(--ease);
}
.tz-toast > div {
  flex: 1;
}
.tz-toast-icon {
  margin-block-start: 4px;
  color: var(--info);
}
.tz-toast[data-tone="success"] .tz-toast-icon {
  color: var(--success);
}
.tz-toast[data-tone="error"] .tz-toast-icon {
  color: var(--danger);
}
.tz-toast-title {
  font-size: var(--text-body);
  font-weight: var(--weight-medium);
}
.tz-toast-description {
  color: var(--text-secondary);
  font-size: var(--text-meta);
  margin-block-start: 2px;
  overflow-wrap: anywhere;
  unicode-bidi: plaintext;
}
.tz-toast[data-state="closed"] {
  animation: tz-toast-out var(--motion-exit) var(--ease);
}
.tz-toast[data-swipe="move"] {
  transform: translateX(var(--radix-toast-swipe-move-x))
    translateY(var(--radix-toast-swipe-move-y));
}
.tz-toast[data-swipe="cancel"] {
  transform: none;
  transition: transform var(--motion-state);
}
.tz-toast[data-swipe="end"] {
  animation: tz-toast-out var(--motion-exit) var(--ease);
}
@keyframes tz-spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes tz-label-in {
  from {
    opacity: 0.5;
    transform: translateY(2px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tz-menu-in {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tz-menu-out {
  to {
    opacity: 0;
    transform: translateY(-3px) scale(0.98);
  }
}
@keyframes tz-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes tz-fade-out {
  to {
    opacity: 0;
  }
}
@keyframes tz-sheet-in {
  from {
    transform: translateX(var(--sheet-offset));
    opacity: 0.8;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
@keyframes tz-sheet-out {
  to {
    transform: translateX(var(--sheet-offset));
    opacity: 0.8;
  }
}
@keyframes tz-toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tz-toast-out {
  to {
    opacity: 0;
    transform: translateY(8px);
  }
}
@media (forced-colors: active) {
  .tz-button,
  .tz-switch,
  .tz-menu,
  .tz-sheet,
  .tz-toast {
    border: 1px solid ButtonText;
  }
  .tz-switch[data-state="checked"],
  .tz-tab-indicator {
    background: Highlight;
  }
