  --motion-state: 0ms;
  --motion-enter: 0ms;
  --motion-exit: 0ms;
}
@media (prefers-reduced-motion: reduce) {
  .tiraz-system {
    --motion-fast: 0ms;
    --motion-state: 0ms;
    --motion-enter: 0ms;
    --motion-exit: 0ms;
  }
  .tiraz-system *,
  .tiraz-system *::before,
  .tiraz-system *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0ms !important;
    scroll-behavior: auto !important;
  }
}
