export type LayoutProps = HTMLAttributes<HTMLDivElement>;
export function Stack({ className = "", ...props }: LayoutProps) {
  return <div {...props} className={`tz-stack ${className}`} />;
}
export function Inline({ className = "", ...props }: LayoutProps) {
  return <div {...props} className={`tz-inline ${className}`} />;
}
export interface TextFieldProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string;
  description?: string;
  error?: string;
}
/** className and native input props target the input; copy is associated by ID. */
export function TextField({
  label,
  description,
  error,
  id,
  className = "",
  "aria-describedby": describedBy,
  ...props
}: TextFieldProps) {
  const uid = useId();
  const controlId = id ?? uid;
  return (
    <div className="tz-field">
      <label htmlFor={controlId}>{label}</label>
      <input
        {...props}
        id={controlId}
        className={`tz-input ${className}`}
        aria-invalid={error ? true : props["aria-invalid"]}
        aria-describedby={
          [
            describedBy,
            description ? `${controlId}-description` : undefined,
            error ? `${controlId}-error` : undefined,
          ]
            .filter(Boolean)
            .join(" ") || undefined
        }
      />
      {description && (
        <p id={`${controlId}-description`} className="tz-field-description">
          {description}
        </p>
      )}
      {error && (
        <p id={`${controlId}-error`} className="tz-pattern-error">
          {error}
        </p>
      )}
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

export interface ActionContext {
  /** Cooperatively abort work on cancellation/unmount; late results are ignored. */
  signal: AbortSignal;
}

export function useAsyncAction() {
  const current = useRef<AbortController | null>(null);
  const [state, setState] = useState<"idle" | "loading" | "success" | "error">(
    "idle",
  );
  const cancel = useCallback(() => {
    const previous = current.current;
    current.current = null;
    previous?.abort();
    setState("idle");
  }, []);
  useEffect(
    () => () => {
      const previous = current.current;
      current.current = null;
      previous?.abort();
    },
    [],
  );

  async function run(
    operation: (context: ActionContext) => Promise<void>,
    onSuccess?: () => void,
  ) {
    if (current.current) return;
    const controller = new AbortController();
    current.current = controller;
    setState("loading");
    try {
      await operation({ signal: controller.signal });
      if (current.current !== controller) return;
      current.current = null;
      setState("success");
      onSuccess?.();
    } catch {
      if (current.current !== controller) return;
      current.current = null;
      setState("error");
    }
  }
  return { state, busy: state === "loading", run, cancel };
}

